tool.command:

  ln -f -s ${input_top_path} ${input_top_path}_`echo $$`.${input_top_path.ext};

  ln -f -s ${input_traj_path} ${input_traj_path}_`echo $$`.${input_traj_path.ext};

#if $config.sele == "option1":
    ln -s -f ${config.properties} ${config.properties}_`echo $$`.${config.properties.ext};
  #end if

mda_hole

#if $config.sele == "option1":
    --config ${config.properties}_`echo $$`.${config.properties.ext}
  #else if $config.sele == "option2":
    --config '${config.jsonstr}'
  #else if $config.sele == "option3":
    --config '__oc____dq__properties__dq__:__oc____dq__start__dq__:${properties.start},__dq__stop__dq__:${properties.stop},__dq__steps__dq__:${properties.steps},__dq__executable__dq__:__dq__${properties.executable}__dq__,__dq__select__dq__:__dq__${properties.select}__dq__,__dq__cpoint__dq__:${properties.cpoint},__dq__cvect__dq__:${properties.cvect},__dq__sample__dq__:${properties.sample},__dq__end_radius__dq__:${properties.end_radius},__dq__dot_density__dq__:${properties.dot_density}__cc____cc__'
  #end if

  #if str($input_top_path) != 'None':
    --input_top_path ${input_top_path}_`echo $$`.${input_top_path.ext}
  #end if

  #if str($input_traj_path) != 'None':
    --input_traj_path ${input_traj_path}_`echo $$`.${input_traj_path.ext}
  #end if


  --output_hole_path $outname_output_hole_path

  --output_csv_path $outname_output_csv_path
;
#if $config.sele == "option1":
    rm -f ${config.properties}_`echo $$`.${config.properties.ext};
  #end if

  rm -f ${input_top_path}_`echo $$`.${input_top_path.ext};

  rm -f ${input_traj_path}_`echo $$`.${input_traj_path.ext};


  if test -f $outname_output_hole_path; then mv $outname_output_hole_path $output_hole_path; fi;

  if test -f $outname_output_csv_path; then mv $outname_output_csv_path $output_csv_path; fi;
